"""Multiset-union classification of componentwise splittings of a partition."""

from __future__ import annotations

from itertools import product
from typing import Dict, List, Sequence, Tuple

Partition = Tuple[int, ...]


def parts(vec: Sequence[int]) -> Partition:
    """The multiset of positive entries, as a weakly decreasing tuple."""
    return tuple(sorted((x for x in vec if x > 0), reverse=True))


def is_partition(vec: Sequence[int]) -> bool:
    """True if vec is weakly decreasing."""
    return all(vec[i] >= vec[i + 1] for i in range(len(vec) - 1))


def multiset_union(alpha: Sequence[int], beta: Sequence[int]) -> Partition:
    """The pooled multiset of positive parts of alpha and beta."""
    return tuple(sorted(list(parts(alpha)) + list(parts(beta)), reverse=True))


def componentwise_splittings(theta: Sequence[int]) -> List[Tuple[Partition, Partition]]:
    """All unordered pairs (alpha, beta) of partitions with alpha + beta = theta."""
    seen, out = set(), []
    for alpha in product(*[range(t + 1) for t in theta]):
        beta = tuple(t - a for t, a in zip(theta, alpha))
        if not (is_partition(alpha) and is_partition(beta)):
            continue
        key = tuple(sorted([parts(alpha), parts(beta)]))
        if key in seen:
            continue
        seen.add(key)
        out.append((alpha, beta))
    return out


def union_classes(theta: Sequence[int]) -> Dict[Partition, List[Tuple[Partition, Partition]]]:
    """Group the unordered componentwise splittings of theta by multiset union.

    Singleton classes are settled by the quadratic-statistic independence theorem;
    classes of size at least two are exactly the residual difficulty.
    """
    classes: Dict[Partition, List[Tuple[Partition, Partition]]] = {}
    for alpha, beta in componentwise_splittings(theta):
        classes.setdefault(multiset_union(alpha, beta), []).append((alpha, beta))
    return classes


def report(theta: Sequence[int]) -> None:
    classes = union_classes(theta)
    total = sum(len(v) for v in classes.values())
    print(f"theta = {tuple(theta)}: {total} unordered splittings in {len(classes)} union classes")
    for u, pairs in sorted(classes.items()):
        tag = "settled by the Q-layer" if len(pairs) == 1 else "COLLISION"
        pretty = "  ".join(f"{{{parts(a)}, {parts(b)}}}" for a, b in pairs)
        print(f"  union {u}: {tag}\n      {pretty}")


if __name__ == "__main__":
    for theta in [(4,), (3, 2), (4, 2), (5, 3), (4, 3, 2)]:
        report(theta)
        print()

"""Expansion of a product of monomial symmetric functions, graded by the quadratic
statistic Q(d) = sum_i d_i^2."""

from __future__ import annotations

from itertools import permutations
from typing import Dict, List, Sequence, Tuple

Exp = Tuple[int, ...]
Partition = Tuple[int, ...]


def qstat(vec: Sequence[int]) -> int:
    """Q(d) = sum_i d_i^2."""
    return sum(x * x for x in vec)


def parts(vec: Sequence[int]) -> Partition:
    """Positive entries, weakly decreasing."""
    return tuple(sorted((x for x in vec if x > 0), reverse=True))


def embed(lam: Sequence[int], n_vars: int) -> Exp:
    """Pad a partition with zeros to length n_vars."""
    if len(lam) > n_vars:
        raise ValueError("not enough variables")
    return tuple(list(lam) + [0] * (n_vars - len(lam)))


def orbit(vec: Sequence[int]) -> List[Exp]:
    """All distinct rearrangements of vec."""
    return sorted(set(permutations(vec)))


def msym(lam: Sequence[int], n_vars: int) -> Dict[Exp, int]:
    """m_lambda in n_vars variables, as {exponent vector: coefficient}."""
    return {w: 1 for w in orbit(embed(parts(lam), n_vars))}


def poly_mul(f: Dict[Exp, int], g: Dict[Exp, int]) -> Dict[Exp, int]:
    """Product of two polynomials in exponent-vector form."""
    out: Dict[Exp, int] = {}
    for u, cu in f.items():
        for v, cv in g.items():
            w = tuple(a + b for a, b in zip(u, v))
            out[w] = out.get(w, 0) + cu * cv
    return {w: c for w, c in out.items() if c}


def graded_expansion(alpha: Sequence[int], beta: Sequence[int],
                     n_vars: int) -> List[Tuple[int, Partition, int]]:
    """Return [(Q(mu), mu, coefficient of m_mu)] for m_alpha * m_beta, sorted by Q.

    The first entry is guaranteed to be the multiset union of alpha and beta, with a
    strictly positive coefficient counting the disjoint placements of the two factors.
    """
    prod = poly_mul(msym(alpha, n_vars), msym(beta, n_vars))
    seen: Dict[Partition, int] = {}
    for w, c in prod.items():
        mu = parts(w)
        seen.setdefault(mu, c)
    return sorted(((qstat(mu), mu, c) for mu, c in seen.items()), key=lambda t: (t[0], t[1]))


if __name__ == "__main__":
    for alpha, beta in [((3, 1), (2, 2)), ((3, 2), (2, 1)), ((2,), (2,))]:
        n_vars = len(parts(alpha)) + len(parts(beta))
        rows = graded_expansion(alpha, beta, n_vars)
        union = tuple(sorted(list(parts(alpha)) + list(parts(beta)), reverse=True))
        print(f"m_{alpha} * m_{beta}  ({n_vars} variables), union = {union}")
        for q, mu, c in rows:
            flag = "  <-- Q-minimal layer = the union" if mu == union else ""
            print(f"   Q = {q:3d}   {c:3d} * m_{mu}{flag}")
        print()

"""Exact rank certification of linear independence for families of products of
monomial symmetric functions."""

from __future__ import annotations

from fractions import Fraction
from itertools import permutations
from typing import Dict, List, Sequence, Tuple

Exp = Tuple[int, ...]
Partition = Tuple[int, ...]


def parts(vec: Sequence[int]) -> Partition:
    return tuple(sorted((x for x in vec if x > 0), reverse=True))


def embed(lam: Sequence[int], n_vars: int) -> Exp:
    if len(lam) > n_vars:
        raise ValueError("not enough variables")
    return tuple(list(lam) + [0] * (n_vars - len(lam)))


def msym(lam: Sequence[int], n_vars: int) -> Dict[Exp, int]:
    return {w: 1 for w in set(permutations(embed(parts(lam), n_vars)))}


def poly_mul(f: Dict[Exp, int], g: Dict[Exp, int]) -> Dict[Exp, int]:
    out: Dict[Exp, int] = {}
    for u, cu in f.items():
        for v, cv in g.items():
            w = tuple(a + b for a, b in zip(u, v))
            out[w] = out.get(w, 0) + cu * cv
    return {w: c for w, c in out.items() if c}


def exact_rank(rows: List[List[Fraction]]) -> int:
    """Rank of a rational matrix by exact Gauss-Jordan elimination."""
    mat = [r[:] for r in rows]
    n_rows = len(mat)
    n_cols = len(mat[0]) if n_rows else 0
    rank = 0
    for col in range(n_cols):
        pivot = next((r for r in range(rank, n_rows) if mat[r][col] != 0), None)
        if pivot is None:
            continue
        mat[rank], mat[pivot] = mat[pivot], mat[rank]
        pv = mat[rank][col]
        mat[rank] = [x / pv for x in mat[rank]]
        for r in range(n_rows):
            if r != rank and mat[r][col] != 0:
                f = mat[r][col]
                mat[r] = [x - f * y for x, y in zip(mat[r], mat[rank])]
        rank += 1
        if rank == n_rows:
            break
    return rank


def certify_independence(pairs: Sequence[Tuple[Partition, Partition]],
                         n_vars: int | None = None) -> Tuple[int, int]:
    """Return (rank, count) for the family of products m_alpha * m_beta."""
    if n_vars is None:
        n_vars = max(len(parts(a)) + len(parts(b)) for a, b in pairs)
    polys = [poly_mul(msym(a, n_vars), msym(b, n_vars)) for a, b in pairs]
    columns = sorted({w for p in polys for w in p})
    index = {w: j for j, w in enumerate(columns)}
    rows = [[Fraction(0)] * len(columns) for _ in polys]
    for i, p in enumerate(polys):
        for w, c in p.items():
            rows[i][index[w]] = Fraction(c)
    return exact_rank(rows), len(polys)


if __name__ == "__main__":
    families = {
        "splittings of (5,3)": [((5, 3), ()), ((4, 3), (1,)), ((4, 2), (1, 1)),
                                ((3, 3), (2,)), ((3, 2), (2, 1)), ((3, 1), (2, 2))],
        "2x2 rectangle complements": [((2, 2), ()), ((2, 1), (1,)),
                                      ((1, 1), (1, 1)), ((2,), (2,))],
        "one-row splittings of (6)": [((6,), ()), ((5,), (1,)), ((4,), (2,)), ((3,), (3,))],
    }
    for name, fam in families.items():
        rank, count = certify_independence(fam)
        verdict = "independent" if rank == count else "DEPENDENT"
        print(f"{name}: rank {rank} of {count} -> {verdict}")

"""Merge-filtration depth analysis of a union class.

Fix a multiset U of positive parts. All products m_A m_B with A + B = U (as multisets)
share the same bottom layer of the quadratic filtration, so the separation must happen
higher up. A monomial lies in layer k if its shape is obtained from U by k merges, each
fusing two parts a, b into a single part a + b. This routine determines the smallest k
such that layers 0..k already separate every splitting of U.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import permutations
from typing import Dict, List, Sequence, Tuple

Exp = Tuple[int, ...]
Partition = Tuple[int, ...]


def parts(vec: Sequence[int]) -> Partition:
    return tuple(sorted((x for x in vec if x > 0), reverse=True))


def msym(lam: Sequence[int], n_vars: int) -> Dict[Exp, int]:
    padded = tuple(list(parts(lam)) + [0] * (n_vars - len(parts(lam))))
    return {w: 1 for w in set(permutations(padded))}


def poly_mul(f: Dict[Exp, int], g: Dict[Exp, int]) -> Dict[Exp, int]:
    out: Dict[Exp, int] = {}
    for u, cu in f.items():
        for v, cv in g.items():
            w = tuple(a + b for a, b in zip(u, v))
            out[w] = out.get(w, 0) + cu * cv
    return {w: c for w, c in out.items() if c}


def monomial_expansion(f: Dict[Exp, int]) -> Dict[Partition, int]:
    out: Dict[Partition, int] = {}
    for w, c in f.items():
        out.setdefault(parts(w), c)
    return out


def exact_rank(rows: List[List[Fraction]]) -> int:
    mat = [r[:] for r in rows]
    n_rows, n_cols = len(mat), (len(mat[0]) if rows else 0)
    rank = 0
    for col in range(n_cols):
        pivot = next((r for r in range(rank, n_rows) if mat[r][col] != 0), None)
        if pivot is None:
            continue
        mat[rank], mat[pivot] = mat[pivot], mat[rank]
        pv = mat[rank][col]
        mat[rank] = [x / pv for x in mat[rank]]
        for r in range(n_rows):
            if r != rank and mat[r][col] != 0:
                f = mat[r][col]
                mat[r] = [x - f * y for x, y in zip(mat[r], mat[rank])]
        rank += 1
        if rank == n_rows:
            break
    return rank


def multiset_splittings(U: Sequence[int]) -> List[Tuple[Partition, Partition]]:
    """All unordered multiset splittings U = A + B."""
    seen, out = set(), []
    n = len(U)
    for mask in range(1 << n):
        A = parts([U[i] for i in range(n) if mask >> i & 1])
        B = parts([U[i] for i in range(n) if not mask >> i & 1])
        key = tuple(sorted([A, B]))
        if key in seen:
            continue
        seen.add(key)
        out.append((A, B))
    return out


def merge_depth(U: Sequence[int]) -> Tuple[int, int, int]:
    """Return (number of splittings, full rank, smallest sufficient merge depth)."""
    U = parts(U)
    n_vars = len(U)
    splits = multiset_splittings(U)
    expansions = [monomial_expansion(poly_mul(msym(A, n_vars), msym(B, n_vars)))
                  for A, B in splits]
    shapes = sorted({mu for e in expansions for mu in e})
    full = [[Fraction(e.get(mu, 0)) for mu in shapes] for e in expansions]
    rank_full = exact_rank(full)
    depth = -1
    for layer in range(len(U) + 1):
        cols = [mu for mu in shapes if len(U) - len(mu) <= layer]
        sub = [[Fraction(e.get(mu, 0)) for mu in cols] for e in expansions]
        if exact_rank(sub) == len(splits):
            depth = layer
            break
    return len(splits), rank_full, depth


if __name__ == "__main__":
    for U in [(2, 2), (2, 1), (2, 2, 1), (3, 2, 1), (1, 1, 1, 1), (3, 2, 2, 1)]:
        n_split, rank, depth = merge_depth(U)
        status = "independent" if rank == n_split else "DEPENDENT"
        print(f"U = {U}: {n_split} splittings, rank {rank} ({status}), "
              f"layers 0..{depth} suffice")
